/**
 * CLI↔Explorer visualization parity tests (fixture-driven).
 *
 * Each test loads a JSON fixture generated by the canonical Python
 * implementation (`tests/parity/generate_visualization_fixtures.py`) and
 * asserts that the TypeScript helper in `chartMath.ts` produces byte-identical
 * results (within 1e-9 for floats, strict equality for strings/ints/null).
 *
 * To regenerate fixtures (changes the contract):
 *   make parity-fixtures
 * To verify fixtures match the Python source without regenerating:
 *   make parity-check
 *
 * Failure message format:
 *   chart=<name>  case=<id>  input=<json>
 *   expected: <value>  got: <value>
 *   Python source: tests/parity/generate_visualization_fixtures.py
 *   TS source:     results-explorer/src/lib/chartMath.ts
 */

import * as fs from "fs";
import * as path from "path";
import { describe, it, expect } from "vitest";
import {
  colorForCell,
  lightnessForCell,
  speedupRatio,
  vsSlowestRatio,
  deltaPct,
  sortByMagnitudeDesc,
  perQuerySpeedup,
  geomeanMs,
  computePercentile,
  computeBoxStats,
  computeECDFPoints,
  computeRankTable,
} from "@/lib/chartMath";

// ---------------------------------------------------------------------------
// Fixture loading
// ---------------------------------------------------------------------------

// Resolved from the repo root (one level above the results-explorer package root)
// so this path stays valid if this test file moves within the package.
// If fixtures are missing, run `make parity-fixtures`.
const FIXTURES_DIR = path.resolve(process.cwd(), "../tests/parity/fixtures");

interface FixtureCase {
  id: string;
  input: Record<string, unknown>;
  expected: Record<string, unknown>;
}

interface Fixture {
  chart: string;
  version: number;
  cases: FixtureCase[];
}

function loadFixture(name: string): Fixture {
  const filePath = path.join(FIXTURES_DIR, `${name}.json`);
  try {
    const raw = fs.readFileSync(filePath, "utf-8");
    return JSON.parse(raw) as Fixture;
  } catch {
    throw new Error(`Fixture not found: ${filePath}\nRun \`make parity-fixtures\` to regenerate.`);
  }
}

// ---------------------------------------------------------------------------
// Assertion helpers
// ---------------------------------------------------------------------------

const FLOAT_TOLERANCE = 1e-9;

/** Compare a TS result against a Python fixture expected value. */
function assertParity(
  result: unknown,
  expected: unknown,
  context: { chart: string; caseId: string; input: unknown },
): void {
  const { chart, caseId, input } = context;
  const msg = `\nchart=${chart}  case=${caseId}  input=${JSON.stringify(input)}\nPython source: tests/parity/generate_visualization_fixtures.py\nTS source:     results-explorer/src/lib/chartMath.ts`;

  if (expected === null || result === null) {
    // Use toStrictEqual so expected=120/result=null fails (not silently passes).
    expect(result, `expected ${String(expected)}${msg}`).toStrictEqual(expected);
    return;
  }

  if (typeof expected === "number" && typeof result === "number") {
    const diff = Math.abs(result - expected);
    expect(
      diff,
      `float diff ${diff} exceeds tolerance ${FLOAT_TOLERANCE}${msg}\nexpected: ${expected}  got: ${result}`,
    ).toBeLessThan(FLOAT_TOLERANCE);
    return;
  }

  // String equality (e.g. lightnessForCell returns "95%")
  expect(result, msg).toStrictEqual(expected);
}

// ---------------------------------------------------------------------------
// heatmap_color
// ---------------------------------------------------------------------------

describe("parity: heatmap_color (colorForCell)", () => {
  const fixture = loadFixture("heatmap_color");

  for (const c of fixture.cases) {
    const { ms, minInCol } = c.input as { ms: number | null; minInCol: number | null };
    it(`case: ${c.id}`, () => {
      const result = colorForCell(ms, minInCol);
      assertParity(result, c.expected.hue, {
        chart: fixture.chart,
        caseId: c.id,
        input: c.input,
      });
    });
  }
});

