// ---------------------------------------------------------------------------
// sort_by_magnitude_desc
// ---------------------------------------------------------------------------

describe("parity: sort_by_magnitude_desc (sortByMagnitudeDesc)", () => {
  const fixture = loadFixture("sort_by_magnitude_desc");

  for (const c of fixture.cases) {
    const { groups } = c.input as {
      groups: { queryId: string; entries: { deltaPct: number }[] }[];
    };
    const expectedOrder = c.expected.sortedQueryIds as string[];

    it(`case: ${c.id}`, () => {
      const pairs: [string, { deltaPct: number }[]][] = groups.map((g) => [g.queryId, g.entries]);
      const sorted = sortByMagnitudeDesc(pairs);
      const resultOrder = sorted.map(([qid]) => qid);
      expect(
        resultOrder,
        `chart=${fixture.chart}  case=${c.id}\nPython source: tests/parity/generate_visualization_fixtures.py\nTS source: results-explorer/src/lib/chartMath.ts`,
      ).toStrictEqual(expectedOrder);
    });
  }
});

