// ---------------------------------------------------------------------------
// distribution_box - computeBoxStats
// ---------------------------------------------------------------------------

describe("parity: distribution_box (computeBoxStats)", () => {
  const fixture = loadFixture("box_stats");

  for (const c of fixture.cases) {
    const { values } = c.input as { values: (number | null)[] };
    it(`case: ${c.id}`, () => {
      const result = computeBoxStats(values);
      const ctx = { chart: fixture.chart, caseId: c.id, input: c.input };
      if (c.expected === null) {
        assertParity(result, null, ctx);
        return;
      }
      const exp = c.expected as { min: number; q1: number; median: number; q3: number; max: number };
      expect(result, `null result for case ${c.id}`).not.toBeNull();
      assertParity(result!.min, exp.min, ctx);
      assertParity(result!.q1, exp.q1, ctx);
      assertParity(result!.median, exp.median, ctx);
      assertParity(result!.q3, exp.q3, ctx);
      assertParity(result!.max, exp.max, ctx);
    });
  }
});

// ---------------------------------------------------------------------------
// cdf_chart - computeECDFPoints
// ---------------------------------------------------------------------------

describe("parity: cdf_chart (computeECDFPoints)", () => {
  const fixture = loadFixture("cdf_ecdf");

  for (const c of fixture.cases) {
    const { values } = c.input as { values: (number | null)[] };
    const expected = c.expected as unknown as { x: number; y: number }[];
    it(`case: ${c.id}`, () => {
      const result = computeECDFPoints(values);
      const ctx = { chart: fixture.chart, caseId: c.id, input: c.input };
      expect(result.length, `length mismatch for case ${c.id}`).toBe(expected.length);
      for (let i = 0; i < expected.length; i++) {
        assertParity(result[i]!.x, expected[i]!.x, ctx);
        assertParity(result[i]!.y, expected[i]!.y, ctx);
      }
    });
  }
});

// ---------------------------------------------------------------------------
// rank_table - computeRankTable
// ---------------------------------------------------------------------------

describe("parity: rank_table (computeRankTable)", () => {
  const fixture = loadFixture("rank_table");

  for (const c of fixture.cases) {
    const { queryIds, timingsByPlatform } = c.input as {
      queryIds: string[];
      timingsByPlatform: Record<string, number | null>[];
    };
    const expected = (c.expected as { ranks: Record<string, (number | null)[]> }).ranks;
    it(`case: ${c.id}`, () => {
      const result = computeRankTable(queryIds, timingsByPlatform);
      const ctx = { chart: fixture.chart, caseId: c.id, input: c.input };
      expect(Object.keys(result).sort(), `query-id set mismatch for case ${c.id}`).toStrictEqual(
        Object.keys(expected).sort(),
      );
      for (const qid of Object.keys(expected)) {
        const expRow = expected[qid]!;
        const resRow = result[qid]!;
        expect(resRow.length, `row length mismatch ${qid}`).toBe(expRow.length);
        for (let i = 0; i < expRow.length; i++) {
          assertParity(resRow[i]!, expRow[i]!, ctx);
        }
      }
    });
  }
});

// ---------------------------------------------------------------------------
// percentile_ladder - computePercentile
// ---------------------------------------------------------------------------

describe("parity: percentile_ladder (computePercentile)", () => {
  const fixture = loadFixture("percentile_ladder");

  for (const c of fixture.cases) {
    // Cases with "values" + "p" test raw computePercentile.
    // Cases with "display_ms_values" test the aggregated stats shape (schema-only, no TS math).
    if (!("values" in c.input)) continue;

    const { values, p } = c.input as { values: number[]; p: number };
    it(`case: ${c.id}`, () => {
      const result = computePercentile(values, p);
      assertParity(result, c.expected.result, {
        chart: fixture.chart,
        caseId: c.id,
        input: c.input,
      });
    });
  }
});
